def act(obs, state):
    if "plan" not in state:
        plan = []
        cx, cy = WORLD_W // 2, WORLD_H // 2

        # Place two coal power plants with wires connecting to zones
        # Layout: left=residential, center=commercial, right=industrial
        # Use a horizontal road spine with vertical wire feeders

        # Power plant positions
        plan.append((Tool.COALPOWER, cx - 30, cy))
        plan.append((Tool.COALPOWER, cx + 20, cy))

        # Wire spine connecting both plants horizontally
        for x in range(cx - 28, cx + 22):
            plan.append((Tool.WIRE, x, cy))

        # Road parallel to wire spine (one row above)
        for x in range(cx - 30, cx + 25):
            plan.append((Tool.ROAD, x, cy - 1))

        # Road parallel to wire spine (one row below)
        for x in range(cx - 30, cx + 25):
            plan.append((Tool.ROAD, x, cy + 1))

        # Residential cluster - left side
        # Wire feeders and zones on both sides of wire spine
        bx = cx - 20
        for dy in range(-12, 13, 3):
            # zones above the spine
            if cy + dy - 1 > 3 and cy + dy - 1 < WORLD_H - 3:
                plan.append((Tool.RESIDENTIAL, bx, cy + dy - 5))
                plan.append((Tool.RESIDENTIAL, bx + 4, cy + dy - 5))
            # zones below the spine
            if cy + dy + 5 < WORLD_H - 3 and cy + dy + 5 > 3:
                plan.append((Tool.RESIDENTIAL, bx, cy + dy + 5))
                plan.append((Tool.RESIDENTIAL, bx + 4, cy + dy + 5))

        # Vertical wire feeders from spine to zones (left cluster)
        for x in [bx, bx + 4]:
            for y in range(cy - 12, cy + 13):
                if y != cy:  # don't overwrite power plant area
                    plan.append((Tool.WIRE, x, y))

        # Vertical roads next to wire feeders
        for x in [bx + 1, bx + 5]:
            for y in range(cy - 12, cy + 13):
                plan.append((Tool.ROAD, x, y))

        # Commercial cluster - center
        bx = cx
        for dy in [-6, -3, 0, 3, 6]:
            if cy + dy - 5 > 3:
                plan.append((Tool.COMMERCIAL, bx, cy + dy - 5))
            if cy + dy + 5 < WORLD_H - 3:
                plan.append((Tool.COMMERCIAL, bx, cy + dy + 5))

        # Wire feeder for commercial
        for y in range(cy - 12, cy + 13):
            plan.append((Tool.WIRE, bx, y))
        for y in range(cy - 12, cy + 13):
            plan.append((Tool.ROAD, bx + 1, y))

        # Industrial cluster - right side
        bx = cx + 15
        for dy in range(-12, 13, 3):
            if cy + dy - 5 > 3:
                plan.append((Tool.INDUSTRIAL, bx, cy + dy - 5))
                plan.append((Tool.INDUSTRIAL, bx + 4, cy + dy - 5))
            if cy + dy + 5 < WORLD_H - 3:
                plan.append((Tool.INDUSTRIAL, bx, cy + dy + 5))
                plan.append((Tool.INDUSTRIAL, bx + 4, cy + dy + 5))

        # Wire and road feeders for industrial
        for x in [bx, bx + 4]:
            for y in range(cy - 12, cy + 13):
                plan.append((Tool.WIRE, x, y))
        for x in [bx + 1, bx + 5]:
            for y in range(cy - 12, cy + 13):
                plan.append((Tool.ROAD, x, y))

        # Cross roads connecting vertical feeders to horizontal spine
        for x in range(cx - 30, cx + 25):
            plan.append((Tool.ROAD, x, cy - 6))
            plan.append((Tool.ROAD, x, cy + 6))

        # Add police and fire stations for coverage
        plan.append((Tool.FIRESTATION, cx - 10, cy - 10))
        plan.append((Tool.POLICESTATION, cx + 5, cy + 10))

        state["plan"] = plan
        state["i"] = 0

    i = state["i"]
    plan = state["plan"]
    if i >= len(plan):
        return None
    state["i"] = i + 1
    tool, x, y = plan[i]
    # clamp coords
    x = max(0, min(WORLD_W - 1, x))
    y = max(0, min(WORLD_H - 1, y))
    return (tool, x, y)

def build_plan():
    plan = []

    # Central neighborhood with a grid layout
    # Power plant at center-left, horizontal wire spine, roads forming a grid

    # --- Neighborhood 1: compact grid around (30, 40) ---
    cx1, cy1 = 30, 45

    # Coal power plant
    plan.append((Tool.COALPOWER, cx1, cy1))

    # Horizontal wire spine going right from plant
    for dx in range(1, 25):
        plan.append((Tool.WIRE, cx1 + dx, cy1))

    # Two horizontal roads (above and below the wire spine)
    for dx in range(0, 30):
        plan.append((Tool.ROAD, cx1 + dx, cy1 - 3))
        plan.append((Tool.ROAD, cx1 + dx, cy1 + 3))

    # Vertical road connecting the two horizontal roads on right side
    for dy in range(-3, 4):
        plan.append((Tool.ROAD, cx1 + 27, cy1 + dy))

    # Zones between the roads (center row at cy1, zones above and below roads)
    # Residential above top road
    for i, dx in enumerate(range(3, 28, 3)):
        plan.append((Tool.RESIDENTIAL, cx1 + dx, cy1 - 6))
    # Commercial below bottom road
    for i, dx in enumerate(range(3, 28, 3)):
        if i % 2 == 0:
            plan.append((Tool.COMMERCIAL, cx1 + dx, cy1 + 6))
        else:
            plan.append((Tool.INDUSTRIAL, cx1 + dx, cy1 + 6))
    # Mixed zones between the roads (at wire spine level)
    for i, dx in enumerate(range(3, 25, 3)):
        if i % 3 == 0:
            plan.append((Tool.RESIDENTIAL, cx1 + dx, cy1))
        elif i % 3 == 1:
            plan.append((Tool.COMMERCIAL, cx1 + dx, cy1))
        else:
            plan.append((Tool.INDUSTRIAL, cx1 + dx, cy1))

    # Add vertical wires to connect zones above/below to spine
    for dx in range(3, 25, 3):
        for dy in [-1, -2, 1, 2]:
            plan.append((Tool.WIRE, cx1 + dx, cy1 + dy))

    # Fire and police stations
    plan.append((Tool.FIRESTATION, cx1 + 3, cy1 - 9))
    plan.append((Tool.POLICESTATION, cx1 + 24, cy1 - 9))

    # --- Neighborhood 2: right side, similar grid around (80, 55) ---
    cx2, cy2 = 80, 55

    # Nuclear power plant for more power
    plan.append((Tool.NUCLEARPOWER, cx2, cy2))

    # Horizontal wire spine going right from plant
    for dx in range(1, 25):
        plan.append((Tool.WIRE, cx2 + dx, cy2))

    # Two horizontal roads
    for dx in range(0, 30):
        plan.append((Tool.ROAD, cx2 + dx, cy2 - 3))
        plan.append((Tool.ROAD, cx2 + dx, cy2 + 3))

    # Vertical connector
    for dy in range(-3, 4):
        plan.append((Tool.ROAD, cx2 + 27, cy2 + dy))

    # Zones - more commercial/industrial heavy
    for i, dx in enumerate(range(3, 28, 3)):
        if i % 2 == 0:
            plan.append((Tool.COMMERCIAL, cx2 + dx, cy2 - 6))
        else:
            plan.append((Tool.RESIDENTIAL, cx2 + dx, cy2 - 6))
    for i, dx in enumerate(range(3, 28, 3)):
        plan.append((Tool.INDUSTRIAL, cx2 + dx, cy2 + 6))
    for i, dx in enumerate(range(3, 25, 3)):
        if i % 3 == 0:
            plan.append((Tool.COMMERCIAL, cx2 + dx, cy2))
        elif i % 3 == 1:
            plan.append((Tool.RESIDENTIAL, cx2 + dx, cy2))
        else:
            plan.append((Tool.COMMERCIAL, cx2 + dx, cy2))

    # Vertical wires for zones
    for dx in range(3, 25, 3):
        for dy in [-1, -2, 1, 2]:
            plan.append((Tool.WIRE, cx2 + dx, cy2 + dy))

    # Services
    plan.append((Tool.FIRESTATION, cx2 + 3, cy2 + 9))
    plan.append((Tool.POLICESTATION, cx2 + 24, cy2 + 9))

    # Connect the two neighborhoods with a road
    connect_y = 48
    for x in range(cx1 + 27, cx2 + 1):
        plan.append((Tool.ROAD, x, connect_y))
    # Also wire connection between neighborhoods
    for x in range(cx1 + 24, cx2 + 1):
        plan.append((Tool.WIRE, x, cy1 + 1))

    # Add extra residential rows above neighborhood 1
    plan.append((Tool.COALPOWER, cx1, cy1 - 15))
    for dx in range(1, 20):
        plan.append((Tool.WIRE, cx1 + dx, cy1 - 15))
    for dx in range(0, 25):
        plan.append((Tool.ROAD, cx1 + dx, cy1 - 12))
    for i, dx in enumerate(range(3, 22, 3)):
        plan.append((Tool.RESIDENTIAL, cx1 + dx, cy1 - 15))
        plan.append((Tool.RESIDENTIAL, cx1 + dx, cy1 - 18))
    for dx in range(3, 22, 3):
        for dy in [-1, 1]:
            plan.append((Tool.WIRE, cx1 + dx, cy1 - 15 + dy))

    return plan


def act(obs, state):
    if "plan" not in state:
        state["plan"] = build_plan()
        state["i"] = 0
    i = state["i"]
    plan = state["plan"]
    if i >= len(plan):
        return None
    state["i"] = i + 1
    return plan[i]
